    m = stack.pop()
    if m not in seen:
        seen.add(m); stack += imports(m)
total = sum(1 for _, _, fs in os.walk('AlgebraicJacobian') for f in fs
            if f.endswith('.lean'))
print(f'{len(seen)} of {total} project modules reachable from the headline')

# variant 2: root
seen2, stack2 = set(), ['AlgebraicJacobian']
while stack2:
    m = stack2.pop()
    if m not in seen2:
        seen2.add(m); stack2 += imports(m)
print(f'{len(seen2)} reachable from AlgebraicJacobian root (incl. root itself)')
ondisk = set()
for r,_,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'):
            ondisk.add(os.path.join(r,f)[:-5].replace('/','.'))
print('on-disk modules:', len(ondisk))
unrooted = sorted(ondisk - seen2)
